effect.shader:
vec4 preMultiplicada(vec4 c) { return vec4(c.rgb * c.a, c.a); }

// O filtro linear da GPU, à mão, sobre a camada PRÉ-multiplicada (a textura do AM é assim): os 4 pixels em volta,
// presos à borda como o CLAMP_TO_EDGE.
vec4 camadaNoPonto(vec2 uv) {
    ivec2 T = textureSize(inputImg, 0);
    vec2 p = uv * vec2(T) - 0.5;
    vec2 i = floor(p);
    vec2 f = p - i;
    ivec2 a = ivec2(i);
    ivec2 m = T - 1;
    vec4 c00 = preMultiplicada(texelFetch(inputImg, clamp(a, ivec2(0), m), 0));
    vec4 c10 = preMultiplicada(texelFetch(inputImg, clamp(a + ivec2(1, 0), ivec2(0), m), 0));
    vec4 c01 = preMultiplicada(texelFetch(inputImg, clamp(a + ivec2(0, 1), ivec2(0), m), 0));
    vec4 c11 = preMultiplicada(texelFetch(inputImg, clamp(a + ivec2(1, 1), ivec2(0), m), 0));
    return mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);
}

// A volta da `acCamadaParaTela`: UV da tela → UV do buffer da camada.
vec2 naCamada(vec2 t) {
    vec3 c = inverse(acCamadaParaTela) * vec3(t, 1.0);
    return c.xy / c.z;
}

void main() {
    // O pixel na tela (na tela, a identidade; no filho de grupo, o buffer dele levado à tela do grupo) e, de lá, a
    // coordenada da camada do AM: o retângulo do conteúdo de 0 a 1, com o meio no meio do buffer (o buffer cobre a
    // composição, `acTamanhoDaTela`).
    vec2 conteudo = max(acTamanhoDaCamada, vec2(1e-6));
    vec2 st = 0.5 + (naCamada(acTela(acScreenNorm)) - 0.5) * acTamanhoDaTela / conteudo;

    // A conta do AM, linha por linha.
    float str = strength / 2.0;
    st -= 0.5;
    st *= 2.0;
    float xdiv = 1. + (1. - pow(abs(st.y), 2.0)) * -str;
    float ydiv = 1. + (1. - pow(abs(st.x), 2.0)) * str;
    xdiv = clamp(xdiv, 0., 2.);
    ydiv = clamp(ydiv, 0., 2.);
    st.x /= xdiv;
    st.y /= ydiv;
    st /= 2.0;
    st += 0.5;

    // De volta ao buffer da camada e à imagem de entrada: na tela (a entrada é a camada já na tela), pela
    // `acCamadaParaTela` sem a divisão da perspectiva quando ela é afim (como o `acLayerToScreen` do AM: o ponto
    // infinito segue infinito, e não vira NaN na divisão); no filho de grupo, a própria UV do buffer.
    vec2 b = 0.5 + (st - 0.5) * conteudo / acTamanhoDaTela;
    vec2 uv = b;
    if (acParaTela == mat3(1.0)) {
        vec3 c = acCamadaParaTela * vec3(b, 1.0);
        bool afim = acCamadaParaTela[0].z == 0.0 && acCamadaParaTela[1].z == 0.0 && acCamadaParaTela[2].z == 1.0;
        uv = afim ? c.xy : c.xy / c.z;
    }

    // Ponto infinito ou NaN (longe da caixa, a divisão chegou a 0): a GPU decide, como no AM.
    bool foraDaConta = any(isinf(uv)) || any(isnan(uv));
    vec4 c = foraDaConta ? preMultiplicada(texture(inputImg, uv)) : camadaNoPonto(uv);
    fragColor = c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}
